import React, { useState, useEffect } from 'react';
import { useLocation } from 'react-router-dom';

const Chat = () => {
  const location = useLocation();
  const { personality } = location.state || {};  // '/settings'에서 전달된 값
  const [userInput, setUserInput] = useState('');
  const [chatHistory, setChatHistory] = useState([]);
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [error, setError] = useState(null);

  // 현재 날짜와 시간을 반환하는 함수 (24시간 기준, 분까지만 표시)
  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',  // 요일을 포함하도록 설정
    }); // 예: "2025년 1월 11일 금요일"
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false, // 24시간 형식
    }); // 예: "15:05"

    return `${date} ${time}`; // 예: "2025년 1월 11일 금요일 15:05"
  };

  // 전송한 시간과 응답받은 시간 추가하여 메시지 기록
  const handleSendMessage = async () => {
    if (userInput.trim() === "") return;

    // 사용자의 메시지와 전송 시간을 추가
    const sentTime = getCurrentDateTime();
    const newMessage = { sender: "user", message: userInput, time: sentTime };
    setChatHistory((prevHistory) => [...prevHistory, newMessage]);

    // 입력창 비우기
    setUserInput("");

    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ user_input: userInput, personality }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || "오류가 발생했습니다.");
      }

      const data = await response.json();
      const chatbotMessage = data.response;

      // 챗봇 응답 시간 기록
      const receivedTime = getCurrentDateTime();
      // 챗봇의 응답과 응답 시간을 추가
      setChatHistory((prevHistory) => [
        ...prevHistory,
        { sender: "chatbot", message: chatbotMessage, time: receivedTime },
      ]);
    } catch (error) {
      console.error("Error fetching chatbot response:", error);
      setError(error.message);

      // 욕설이 포함된 메시지가 있는 경우
      if (error.message.includes("부적절한 내용")) {
        alert("부적절한 내용은 사용할 수 없습니다. 다시 입력해주세요.");

        // 마지막으로 추가된 사용자 메시지만 삭제
        setChatHistory((prevHistory) => prevHistory.slice(0, -1));
      }
    }
  };

  // 컴포넌트가 마운트될 때마다 시간을 갱신하도록 설정
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000); // 1초마다 시간을 갱신

    // 컴포넌트가 언마운트될 때 interval을 클리어
    return () => clearInterval(interval);
  }, []);

  // 엔터 키를 눌렀을 때 메시지를 전송하도록 처리
  const handleKeyDown = (e) => {
    if (e.key === "Enter") {
      handleSendMessage();
    }
  };

  return (
    <div>
      {/* 오늘 날짜와 시간을 맨 위에 실시간으로 표시 */}
      <div>
        <strong>{currentDateTime}</strong>
      </div>
      <div>
        {chatHistory.map((chat, index) => (
          <div key={index} className={chat.sender}>
            <strong>{chat.sender === "user" ? "User" : "Chatbot"}:</strong> {chat.message}
            <div><em>{chat.time}</em></div> {/* 전송/응답 시간 표시 */}
          </div>
        ))}
      </div>
      <div>
        <input
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}  // 엔터 키 입력 감지
        />
        <button onClick={handleSendMessage}>전송</button>
      </div>
    </div>
  );
};

export default Chat;
